/* 全局文字渲染优化 */
*:not([class*="icon"]):not(i) {
    /* 1. 开启抗锯齿，让文字边缘更清晰平滑，稍微变细 */
    -webkit-font-smoothing: antialiased !important;
    -moz-osx-font-smoothing: grayscale !important;

    /* 2. 使用半透明阴影代替纯灰色 */
    /* 0.05px 的位移比 0.1px 更细腻，rgba(0,0,0,0.15) 模拟墨水晕染感 */
    text-shadow: 0 0 1px rgba(0, 0, 0, 0.15) !important;
    
    /* 3. 如果你觉得原来的太淡，可以用下面这一行代替上一行 (更接近你原来的效果) */
    /* text-shadow: 0.1px 0.1px 1px rgba(100, 100, 100, 0.3) !important; */
}

/* 这是一个保护措施：防止代码破坏图标字体（如 FontAwesome） */
/* 如果发现网页图标变模糊，这段代码很重要 */
